int add_one(int x) { return x + 1; }
int mul_two(int x) { return x * 2; }
int err_op(int x) { return 0; }

// Define function pointer signature
typedef int (*ActionPtr)(int);

// Dispatch Table (Fast O(1) lookup)
ActionPtr handler_map[] = {
    add_one,
    mul_two,
    err_op
};

enum Command { CMD_ADD = 0, CMD_MUL = 1 };

int input_val = 10;
int cmd_id = CMD_MUL;

// Runtime dispatch (replaces large switch statement)
int output = handler_map[cmd_id](input_val);
